gid_t target_gid = 2000;
int result;

// Attempt to change the filesystem group ID
result = setfsgid(target_gid);

if (result == -1) {
    // EPERM if caller is not superuser and target_gid
    // doesn't match real, effective, or saved GID.
    // EINVAL if target_gid is invalid.
    perror("setfsgid");
} else {
    // Filesystem group ID successfully changed.
    printf("FSGID set to %d\n", target_gid);
}
